<template><div><nav class="dp-account-actions" :aria-label="$t('Asset actions')"><Link :href="route('wallets.deposit.crypto','USDT')"><span><action-icon name="deposit"/></span>{{ $t('Add funds') }}</Link><button ref="sendButton" @click="open"><span><action-icon name="withdraw"/></span>{{ $t('Send') }}</button><Link :href="route('wallets.transfer')"><span><action-icon name="transfer"/></span>{{ $t('Transfer') }}</Link><Link :href="route('stakings',{staking_type:0})"><span><action-icon name="earn"/></span>{{ $t('Wealth') }}</Link></nav><div v-if="sending" class="dp-send-overlay" @click.self="close" @keydown.esc="close" @keydown.tab="trap"><section ref="sheet" class="dp-send-sheet" role="dialog" aria-modal="true" :aria-label="$t('Send')"><header><h2>{{ $t('Send') }}</h2><button ref="closeButton" @click="close" :aria-label="$t('Close')">×</button></header><Link :href="route('wallets.withdraw.crypto','USDT')"><action-icon name="withdraw"/><span><b>{{ $t('On-chain withdrawal') }}</b><small>{{ $t('Send to a blockchain address') }}</small></span>›</Link><Link :href="route('wallets.withdraw.crypto',{symbol:'USDT',type:'internal'})"><action-icon name="transfer"/><span><b>{{ $t('Internal withdrawal') }}</b><small>{{ $t('Send to another Deepro account') }}</small></span>›</Link></section></div></div></template><script>import ActionIcon from './ActionIcon.vue';export default{components:{ActionIcon},data:()=>({sending:false,previousOverflow:''}),beforeDestroy(){if(this.sending)document.body.style.overflow=this.previousOverflow},methods:{open(){this.previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';this.sending=true;this.$nextTick(()=>this.$refs.closeButton.focus())},close(){this.sending=false;document.body.style.overflow=this.previousOverflow;this.$refs.sendButton.focus()},trap(e){const items=this.$refs.sheet.querySelectorAll('button,a[href]');const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}};</script>
